import type { SyntaxNode } from "@lezer/common";
import { parser } from "./query/parser";
import * as T from "./query/parser.terms";
import { qAnd, qConst, qContent, qFileName, qNot, qOr, qRepo, qRepoSet, qSymbol, type Q, type RawFlag } from "./ir";
import linguistLanguages from "./linguistLanguages.json" with { type: "json" };

/**
 * Search syntax string -> query IR.
 *
 * Grammar and tokenizers live in ./query (Lezer, generated by `pnpm --filter @falkon/shared gen:parser`).
 * Semantics follow the reference engine exactly, quirks included, so results line up one to one; the
 * differential in parity/grammar checks it. Notable quirks kept on purpose:
 *  - quotes are stripped but `\"` inside them is not unescaped;
 *  - `sym:` is always a regex, `file:` always a file-name regex, even in literal mode;
 *  - `rev:*` becomes an empty branch pattern (every branch);
 *  - `()` is match-nothing.
 */

export interface ParseOptions {
  regex?: boolean;
  caseSensitive?: boolean;
  /** Search contexts by name (config `contexts`). An unknown name throws SearchContextNotFoundError. */
  contexts?: Record<string, string[]>;
  /** Extra repo names a `repo:` regex also selects (knowledge repos whose owner matches it). */
  expandRepoRegexp?: (regexp: string) => string[];
  /** Expands a `reposet:` list (adds the knowledge repos of the named repos). */
  expandRepoSet?: (names: string[]) => string[];
}

export class QuerySyntaxError extends Error {}
export class SearchContextNotFoundError extends Error {}

const strict = parser.configure({ strict: true });
const strictRegex = parser.configure({ strict: true, dialect: "regex" });

const languageByLower = new Map((linguistLanguages as string[]).map((l) => [l.toLowerCase(), l]));
/** Linguist names are case-sensitive in zoekt; map any casing of a known name to its canonical form. */
export const normalizeLanguage = (v: string) => languageByLower.get(v.toLowerCase()) ?? v;

const children = (n: SyntaxNode) => {
  const out: SyntaxNode[] = [];
  for (let c = n.firstChild; c; c = c.nextSibling) out.push(c);
  return out;
};

const flagValue = (name: string, value: string, map: Record<string, RawFlag | null>): Q => {
  const v = value.toLowerCase();
  if (!(v in map)) throw new QuerySyntaxError(`invalid ${name} value "${value}", expected ${Object.keys(map).join(", ")}`);
  return { raw_config: { flags: map[v] ? [map[v]!] : [] } };
};

export function parseQuery(src: string, options: ParseOptions = {}): Q {
  const regex = options.regex ?? false;
  const caseSensitive = options.caseSensitive ?? false;
  let tree;
  try {
    tree = (regex ? strictRegex : strict).parse(src);
  } catch (e) {
    throw new QuerySyntaxError(`Failed to parse query "${src}" with message: ${(e as Error).message}`);
  }

  const content = (pattern: string) => qContent(pattern, { regex, caseSensitive });
  const repoSet = (names: string[]) => qRepoSet(names);

  const prefix = (node: SyntaxNode): Q => {
    const kw = node.firstChild;
    if (!kw) throw new QuerySyntaxError("empty filter");
    const text = src.slice(kw.from, kw.to);
    const value = text.slice(text.indexOf(":") + 1).replace(/^"|"$/g, "");
    switch (kw.type.id) {
      case T.FileExpr:
        return qFileName(value, caseSensitive);
      case T.RepoExpr: {
        const extra = options.expandRepoRegexp?.(value) ?? [];
        return extra.length ? qOr(qRepo(value), repoSet(extra)) : qRepo(value);
      }
      case T.RevisionExpr:
        return { branch: { pattern: value === "*" ? "" : value, exact: false } };
      case T.ContentExpr:
        return content(value);
      case T.LangExpr:
        return { language: { language: normalizeLanguage(value) } };
      case T.SymExpr:
        return qSymbol({ regexp: { regexp: value, case_sensitive: caseSensitive, file_name: false, content: true } });
      case T.VisibilityExpr:
        return flagValue("visibility", value, { public: "FLAG_ONLY_PUBLIC", private: "FLAG_ONLY_PRIVATE", any: null });
      case T.ArchivedExpr:
        return flagValue("archived", value, { yes: null, no: "FLAG_NO_ARCHIVED", only: "FLAG_ONLY_ARCHIVED" });
      case T.ForkExpr:
        return flagValue("fork", value, { yes: null, no: "FLAG_NO_FORKS", only: "FLAG_ONLY_FORKS" });
      case T.ContextExpr: {
        const repos = options.contexts?.[value];
        if (!repos) throw new SearchContextNotFoundError(`Search context "${value}" not found`);
        return repoSet(repos.map((r) => r.trim()));
      }
      case T.RepoSetExpr: {
        const names = value.split(",").map((r) => r.trim());
        return repoSet(options.expandRepoSet?.(names) ?? names);
      }
    }
    throw new QuerySyntaxError(`unknown filter "${kw.type.name}"`);
  };

  const walk = (node: SyntaxNode): Q => {
    switch (node.type.id) {
      case T.Program:
      case T.ParenExpr: {
        const inner = node.firstChild;
        return inner ? walk(inner) : qConst(false);
      }
      case T.AndExpr:
        return qAnd(...children(node).map(walk));
      case T.OrExpr:
        return qOr(...children(node).map(walk));
      case T.NegateExpr: {
        const inner = node.getChild("PrefixExpr") ?? node.getChild("ParenExpr");
        if (!inner) throw new QuerySyntaxError("nothing to negate");
        return qNot(walk(inner));
      }
      case T.PrefixExpr:
        return prefix(node);
      case T.QuotedTerm:
        return content(src.slice(node.from, node.to).replace(/^"|"$/g, ""));
      case T.Term:
        return content(src.slice(node.from, node.to));
    }
    return qConst(true);
  };

  return walk(tree.topNode);
}
